WITH base AS (SELECT * FROM accounts WHERE status NOT IN ('OPEN', 'FROZEN', 'CLOSED') AND balance >= 72000), accounts_stats AS (SELECT status, CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, ROUND(AVG(balance), 2) AS avg_balance, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(account_type))) AS account_type_values FROM base GROUP BY status, CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT status, opened_cohort, avg_balance, account_type_values FROM accounts_stats
